import { spawnSync } from 'node:child_process';
import { mkdtemp, cp, readFile, writeFile, mkdir, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { strict as assert } from 'node:assert';
const root = '/home/diogo/dev/testmaster';
const source = join(root, 'evals/results/m3-round3-qwen38-medium-2026-10-08T03-41-42-368Z');
const output = join(root, 'validation/results/m3-utility/cli');
await mkdir(output, { recursive: true });
const observations = [];
for (const id of ['m3-bug-02','m3-drift-03','m3-bug-03','m3-env-03','m3-drift-07','m3-drift-08','m3-drift-12']) {
  const ledger = JSON.parse(await readFile(join(source, id+'.json'), 'utf8'));
  const copy = await mkdtemp('/tmp/tm-utility-cli-');
  try {
    await cp(ledger.records.workspace, copy, { recursive: true });
    const env = { ...process.env, HOME:join(copy,'home'),XDG_CONFIG_HOME:join(copy,'home/.config'),XDG_DATA_HOME:join(copy,'home/.local/share'),TESTMASTER_DATA_DIR:join(copy,'repo/.testmaster'),TESTMASTER_OFFLINE:'true',CI:'false' };
    const cli = (args) => {
      const result = spawnSync('/usr/bin/node',[join(root,'apps/cli/dist/main.js'),'--cwd',join(copy,'repo'),...args],{env,encoding:'utf8',timeout:60000});
      assert.equal(result.status,0,JSON.stringify({id,args,stderr:result.stderr,error:String(result.error ?? '')}));
      return result.stdout;
    };
    const runId = ledger.records.transformed.runId;
    const text = cli(['run','analyze',runId]);
    assert.match(text,/Conclusion:/);
    assert.match(text,/Next step:/);
    assert.match(text,/Automatic healing:/);
    const json = JSON.parse(cli(['--output','json','run','analysis',runId]));
    const analyzed = JSON.parse(cli(['--output','json','run','analyze',runId]));
    assert.deepEqual(json.data,analyzed.data);
    assert.deepEqual(Object.keys(json).sort(),['data','requestId','schemaVersion','warnings']);
    assert.ok(json.data.diagnosis);
    await writeFile(join(output,id+'.txt'),text);
    await writeFile(join(output,id+'.json'),JSON.stringify(json.data,null,2)+'\n');
    const markdown=JSON.parse(cli(['--output','json','report','export',runId,'--format','markdown'])).data.content;
    const html=JSON.parse(cli(['--output','json','report','export',runId,'--format','html'])).data.content;
    assert.match(markdown,/Diagnosis/);
    assert.match(html,/Diagnosis/);
    await writeFile(join(output,id+'.md'),markdown);
    await writeFile(join(output,id+'.html'),html);
    const entry={id,runId,diagnosis:json.data.diagnosis,text:true,jsonUnchanged:true,markdown:true,html:true};
    if(ledger.records.proposal){
      const proposalId=ledger.records.proposal.id;
      const review=cli(['heal','review',proposalId]);
      const reviewJson=JSON.parse(cli(['--output','json','heal','review',proposalId]));
      assert.ok(reviewJson.data.preservedAssertions.intact);
      assert.equal(reviewJson.data.approval.proposalId,proposalId);
      assert.match(review,/--expected-version/);
      if(ledger.records.proposal.approvalMode==='policy')assert.ok(reviewJson.data.verification);
      else assert.equal(reviewJson.data.automation.decision,'manual_review_required');
      await writeFile(join(output,id+'-review.txt'),review);
      await writeFile(join(output,id+'-review.json'),JSON.stringify(reviewJson.data,null,2)+'\n');
      entry.review=reviewJson.data;
    }
    observations.push(entry);
    console.log(JSON.stringify({id,analysis:'text+JSON',exports:'markdown+html',healingReview:!!entry.review,conclusion:entry.diagnosis.conclusion.status,absence:entry.diagnosis.observation?.absence}));
  } finally { await rm(copy,{recursive:true,force:true}); }
}
await writeFile(join(output,'summary.json'),JSON.stringify({development:true,registered:false,holdout:false,observations},null,2)+'\n');

scripts.testmaster-m3-assisted-smoke.mjs:
import { cp, mkdtemp, readFile, rm, mkdir, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { strict as assert } from 'node:assert';
import { Application } from '/home/diogo/dev/testmaster/packages/application/dist/index.js';
import { assessAssistedCandidate, loadCorpusDriver } from '/home/diogo/dev/testmaster/tools/dist/evals/m3.js';
const root='/home/diogo/dev/testmaster';
const corpus=JSON.parse(await readFile(join(root,'evals/m3/corpus.json'),'utf8'));
const driver=await loadCorpusDriver(root,corpus);
const outcomes=[];
for(const id of ['m3-drift-07','m3-drift-08','m3-drift-12']){
  const ledger=JSON.parse(await readFile(join(root,'evals/results/m3-round3-qwen38-medium-2026-10-08T03-41-42-368Z',id+'.json'),'utf8'));
  const copy=await mkdtemp('/tmp/tm-utility-assisted-source-');
  let app;
  try{
    await cp(ledger.records.workspace,copy,{recursive:true});
    const cwd=join(copy,'repo'),home=join(copy,'home');
    const env={...process.env,HOME:home,XDG_CONFIG_HOME:join(home,'.config'),XDG_DATA_HOME:join(home,'.local/share'),TESTMASTER_DATA_DIR:join(cwd,'.testmaster'),TESTMASTER_OFFLINE:'true',CI:'false'};
    app=await Application.open({cwd,home,env});
    const proposal=app.healing.get(ledger.records.proposal.id);
    const failed=app.runs.get(proposal.failedRunId);
    const basePlan=app.revisions.get(proposal.baseRevisionId).plan;
    const environmentId=failed.matrixCell.environmentId;
    const port=Number(new URL(failed.matrixCell.baseUrl).port);
    const item=corpus.cases.find(c=>c.id===id);
    const before=JSON.stringify(proposal);
    const active=app.tests.get(proposal.testId).activeRevisionId;
    const result=await assessAssistedCandidate(app,copy,root,corpus,item,driver,proposal,proposal.testId,environmentId,basePlan,port,'tm-utility-control-canary');
    assert.equal(JSON.stringify(app.healing.get(proposal.id)),before);
    assert.equal(app.tests.get(proposal.testId).activeRevisionId,active);
    assert.equal(result.proof.promoted,false);
    assert.equal(result.proof.isolated,true);
    assert.equal(result.proof.assertionsPreserved,true);
    assert.notEqual(result.proof.positiveRunId,result.proof.negativeRunId);
    outcomes.push({id,...result});
    console.log(JSON.stringify({id,proof:result.proof}));
  }finally{app?.close();await rm(copy,{recursive:true,force:true});}
}
await mkdir(join(root,'validation/results/m3-utility'),{recursive:true});
await writeFile(join(root,'validation/results/m3-utility/assisted-candidate-replay.json'),JSON.stringify({development:true,registered:false,holdout:false,outcomes},null,2)+'\n');

