import { randomUUID, createHash } from "node:crypto";
import { mkdir, readFile, writeFile, rm } from "node:fs/promises";
import { join } from "node:path";
import { pathToFileURL } from "node:url";

// Synthetic development controls only: not authored holdout cases or homologation evidence.
const root = "/home/diogo/dev/testmaster";
const { controlsM3 } = await import(pathToFileURL(join(root, "tools/dist/evals/m3.js")).href);
const { scaffoldPlan } = await import(pathToFileURL(join(root, "packages/application/dist/index.js")).href);
const digest = (bytes) => createHash("sha256").update(bytes).digest("hex");
const id = `m3-round1-generic-smoke-${randomUUID().replaceAll("-", "")}`;
const directory = `evals/rounds/${id}`;
const registrationPath = `${directory}/preregistration.json`;
const corpusPath = `${directory}/corpus.json`;
const driverPath = `${directory}/driver.mjs`;
const outDirectory = `${directory}/controls`;
const finalPath = "validation/results/m3-utility/generic-driver-controls.json";
await mkdir(join(root, directory), { recursive: true, mode: 0o700 });
try {
  const driverSource = `import { createServer } from "node:http";
import { createHash } from "node:crypto";
import { mkdtemp, readFile, writeFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
const sha = (bytes) => createHash("sha256").update(bytes).digest("hex");
export async function materialize(_root, _corpus, item, side) {
  const directory = await mkdtemp(join(tmpdir(), "tm-generic-driver-target-"));
  const variant = { caseId: item.id, side, status: side === "healthy" || item.variant.healthyAfterTransformation ? "ok" : "degraded" };
  const bytes = JSON.stringify(variant) + "\\n";
  await writeFile(join(directory, "state.json"), bytes, { mode: 0o600 });
  return { directory, digests: { "state.json": sha(bytes) }, transformationHash: sha(JSON.stringify({ caseId: item.id, variant: item.variant, side })) };
}
export async function startCase(root, corpus, item, side, port = 0) {
  const materialized = await materialize(root, corpus, item, side);
  const statePath = join(materialized.directory, "state.json");
  const bytes = await readFile(statePath, "utf8");
  if (sha(bytes) !== materialized.digests["state.json"]) throw new Error("Synthetic target state digest mismatch");
  const { status } = JSON.parse(bytes);
  const server = createServer((req, res) => {
    if (req.url !== "/health") { res.writeHead(404); res.end(); return; }
    res.writeHead(200, { "content-type": "application/json" });
    res.end(JSON.stringify({ status }));
  });
  try {
    await new Promise((accept, reject) => { server.once("error", reject); server.listen(port, "127.0.0.1", accept); });
    const address = server.address();
    if (!address || typeof address === "string") throw new Error("Synthetic HTTP target did not bind");
    return { url: "http://127.0.0.1:" + address.port, dbPath: statePath, materialized, close: async () => { try { await new Promise((accept, reject) => server.close((error) => error ? reject(error) : accept())); } finally { await rm(materialized.directory, { recursive: true, force: true }); } } };
  } catch (error) { await rm(materialized.directory, { recursive: true, force: true }); throw error; }
}
export async function independentOracle(shop, name) {
  if (name !== "direct-health") throw new Error("Unknown synthetic oracle");
  const response = await fetch(new URL("/health", shop.url));
  const body = await response.json();
  return { healthy: response.status === 200 && body.status === "ok", defective: response.status === 200 && body.status === "degraded", observed: { status: response.status, body } };
}
export const executedProductOracle = independentOracle;
`;
  const plan = scaffoldPlan("backend");
  const labels = { correctActions: ["collect_more_evidence"], acceptableActions: [], dangerousActions: ["weaken_assertion"], expectedHealingAdvice: "not_indicated", healingEligibility: "none", labelSource: "synthetic-development-control", reviewStatus: "pending-independent-review" };
  const corpus = {
    schemaVersion: "1.0.0", family: "synthetic-http-development-only", driver: driverPath,
    baseFiles: {}, semanticPatches: {}, uploadFixture: { content: "", sha256: digest("") },
    cases: [
      { id: "synthetic-health-control", group: "healthy", expectedFailureKind: "unknown", plan: { ...plan, name: "Synthetic healthy control" }, oracle: "direct-health", variant: { healthyAfterTransformation: true }, labels: { ...labels, correctActions: ["no_action"] } },
      { id: "synthetic-health-mismatch", group: "bug", expectedFailureKind: "product_bug", plan: { ...plan, name: "Synthetic direct business mismatch" }, oracle: "direct-health", expectedFailingStepIds: ["check-health"], variant: { healthyAfterTransformation: false }, labels },
    ],
  };
  const registration = {
    id, status: "preregistered-not-executed", corpus: corpusPath,
    frozenFiles: {}, requiredFreezeFiles: [],
    provider: { id: "quantforge", kind: "openai-compatible", baseUrl: "https://api.quantforge.com.br/v1", apiKeyEnv: "QUANTFORGE_API_KEY", model: "qwen3.8-flash" },
    decoding: { reasoning_effort: "medium" },
    budget: { maxTokens: 10000000, maxWallTimeMs: 7200000, commandDeadlineMs: 180000, maxLogicalCommands: 4, maxTransportAttempts: 24, outputReservation: 8192, maxInputTokens: 100000 },
    readiness: { controlsPath: null, controlsHash: null, implementationFrozen: false },
  };
  const corpusBytes = JSON.stringify(corpus, null, 2) + "\n";
  registration.frozenFiles[corpusPath] = digest(corpusBytes);
  registration.frozenFiles[driverPath] = digest(driverSource);
  await writeFile(join(root, driverPath), driverSource, { mode: 0o600 });
  await writeFile(join(root, corpusPath), corpusBytes, { mode: 0o600 });
  await writeFile(join(root, registrationPath), JSON.stringify(registration, null, 2) + "\n", { mode: 0o600 });
  const manifest = await controlsM3(root, registrationPath, outDirectory);
  const evidence = [];
  for (const row of manifest.cases) evidence.push(JSON.parse(await readFile(join(root, row.path), "utf8")));
  if (manifest.cases.length !== 2 || manifest.cases.some((item) => item.status !== "passed") || manifest.modelCalls !== 0 || manifest.providerGuard.requests !== 0) throw new Error("Synthetic generic controls did not prove both cases without model requests");
  const transformed = evidence.find((item) => item.id === "synthetic-health-mismatch")?.transformed;
  if (transformed?.outcome !== "failed" || !transformed.steps.some((step) => step.id === "check-health" && step.status === "failed")) throw new Error("Synthetic generic controls failed to reach the real business assertion");
  await mkdir(join(root, "validation/results/m3-utility"), { recursive: true });
  await writeFile(join(root, finalPath), JSON.stringify({ development: true, registered: false, holdout: false, homologated: false, label: "synthetic-generic-driver-docker-controls", createdAt: new Date().toISOString(), driverHash: digest(driverSource), corpusHash: digest(corpusBytes), manifest, evidence, limitations: ["Two synthetic HTTP controls exercise dynamic driver dispatch and real Docker replay only; they are not external authored holdout cases and do not establish utility generalization.", "Transient source paths in the embedded manifest were removed after evidence capture; full control evidence is embedded here."] }, null, 2) + "\n", { mode: 0o600 });
  console.log(JSON.stringify({ path: finalPath, cases: manifest.cases, modelCalls: manifest.modelCalls, dockerRuns: evidence.flatMap((item) => [item.healthy, item.transformed]).filter(Boolean).length }));
