scripts.testmaster-m3-capability-smoke.mjs:
import { spawnSync } from 'node:child_process';
import { mkdir, writeFile } from 'node:fs/promises';
import { strict as assert } from 'node:assert';
const root='/home/diogo/dev/testmaster';
const out=root+'/validation/results/m3-utility/gates';
await mkdir(out,{recursive:true});
const results=[];
for(const gate of ['m3-assistive-diagnosis','m3-automatic-healing','m3-assisted-healing','m3-ci-integration']){
  const result=spawnSync('/usr/bin/node',[root+'/tools/dist/traceability/cli.js','check','--capability-gate',gate],{encoding:'utf8'});
  assert.equal(result.status,1,'Gate must remain blocked: '+gate);
  const observation=result.stdout+'\n'+result.stderr;
  assert.match(observation,/blocked|absent|unavailable|not recorded|missing/i);
  assert.match(observation,new RegExp(gate));
  assert.doesNotMatch(observation,/protected critical assertion missing/);
  const expectedReason={"m3-assistive-diagnosis":/External-family independently reviewed holdout/,"m3-automatic-healing":/independent security review/,"m3-assisted-healing":/No participant review/,"m3-ci-integration":/cross-owner fork-token isolation/}[gate];
  assert.match(observation,expectedReason);
  await writeFile(out+'/'+gate+'.log',observation);
  results.push({gate,exit:result.status,stdout:result.stdout,stderr:result.stderr});
  console.log(JSON.stringify({gate,exit:result.status,observation}));
}
const milestone=spawnSync('/usr/bin/node',[root+'/tools/dist/traceability/cli.js','check','--milestone-gate','M3'],{encoding:'utf8'});
assert.equal(milestone.status,1,'M3 must remain red');
assert.match(milestone.stderr,/M3-01|model-loop-m3-round3|holdout/);
assert.doesNotMatch(milestone.stderr,/protected critical assertion missing/);
await writeFile(out+'/milestone-M3.log',milestone.stdout+'\n'+milestone.stderr);
await writeFile(out+'/summary.json',JSON.stringify({results,milestone:{exit:milestone.status,stderr:milestone.stderr}},null,2)+'\n');
console.log(JSON.stringify({milestone:'M3',exit:milestone.status,red:true}));
